#include <iostream>
#include <vector>

int main()
{
    int n{};
    if (!(std::cin >> n) || n <= 0)
    {
        std::cout << "min 0\nmax 0\nsum 0\nabove 0\n";
        return 0;
    }

    std::vector<int> v;
    long long sum{};

    for (int i = 0; i < n; ++i)
    {
        int x{};
        std::cin >> x;
        v.push_back(x);
        sum += x;
    }

    int lo{ v[0] };
    int hi{ v[0] };
    for (int x : v)
    {
        if (x < lo) lo = x;
        if (x > hi) hi = x;
    }

    int above{};
    for (int x : v)
        if (static_cast<long long>(x) * n > sum) ++above;

    std::cout << "min " << lo << "\n";
    std::cout << "max " << hi << "\n";
    std::cout << "sum " << sum << "\n";
    std::cout << "above " << above << "\n";

    return 0;
}
